    public Settings capture_state(Control owner){finish_pending(owner);return new Settings{["document"]=_documents.snapshot(Document(owner)),["document_path"]=owner.Get("document_path"),["dirty"]=owner.Get("_dirty"),["undo"]=owner.Get("_undo").AsGodotArray().Duplicate(),["redo"]=owner.Get("_redo").AsGodotArray().Duplicate(),["ui"]=ui_state(owner)};}
    public Settings ui_state(Control owner)
    {
        var canvas=Canvas(owner);var result=new Settings();foreach(string key in new[]{"zoom","pan","tool","pixel_mode","pixel_box_select","correction_strength","brush_type","soften_strength","correction_scale","paint_selection_only","pixel_match_all","edge_magnet","edge_threshold","object_threshold","painting_mode","material_strength","selection_alpha","selection_falloff"})result[key]=canvas.Get(key);result["selected"]=canvas.Get("selected").AsGodotArray().Duplicate();result["effects_open"]=owner.Get("_effects_open");result["effects_filter"]=owner.Get("_effects_filter");result["stroke_correct"]=canvas.Get("brush_type").AsString()=="stroke_correct";result["warp_settings"]=_warp.settings(canvas.Get("warp_tool").As<RefCounted>());result["repair_settings"]=_repair.settings(canvas.Get("repair_tool").As<RefCounted>());result["paint_tool_settings"]=owner.Get("_paint_tool_settings").AsGodotDictionary().Duplicate(true);result["main_split"]=FirstSplit(owner.Get("_main_split").As<SplitContainer>());result["side_split"]=FirstSplit(owner.Get("_side_split").As<SplitContainer>());foreach(var field in new[]{("macros","_macros",true),("variants","_variants",false),("custom_shortcuts","_custom_shortcuts",false)})result[field.Item1]=owner.Get(field.Item2).AsGodotDictionary().Duplicate(field.Item3);result["recent_assets"]=owner.Get("_recent_assets").AsGodotArray().Duplicate();return result;
