        Touch(owner);if(owner.Get("_before").AsGodotObject()!=null||owner.Get("document").AsGodotObject()==null)return;var document=Document(owner);var before=_documents.snapshot(document);owner.Set("_before",before);owner.Set("_selection_transform_active",false);if(before.Get("pixel_selection").AsGodotObject()!=null&&before.Get("pixel_selection_reference").AsGodotObject()==null){var layer=_documents.layer_for_id(before,before.Get("pixel_selection_owner").AsString());if(layer!=null){before.Set("pixel_selection_reference",_layers.copy_layer(layer));before.Set("pixel_selection_reference_world",_documents.world_transform(before,layer));document.Set("pixel_selection_reference",_layers.copy_layer(layer));document.Set("pixel_selection_reference_world",before.Get("pixel_selection_reference_world"));}}foreach(var entry in document.Get("layers").AsGodotArray()){var layer=entry.As<Resource>();var properties=layer.Get("properties").AsGodotDictionary();if(Get(properties,"values_selection").VariantType!=Variant.Type.Nil&&!properties.ContainsKey("values_selection_frame")){properties["values_selection_frame"]=_documents.world_transform(document,layer);properties["values_selection_dimensions"]=layer.Get("dimensions");}}
