        sync_selection_transform(owner);sync_linked_styles(owner);Touch(owner);var renderer=Renderer(owner);if(renderer.Get("exporting").AsBool()){owner.Set("_refresh_pending",true);return;}var canvas=Canvas(owner);if(canvas.Get("_drag").AsString().StartsWith("resize",StringComparison.Ordinal)||owner.Get("_sizing_preview").AsBool()){_renderer.sync_transforms(renderer,Document(owner));canvas.Set("preview",_renderer.texture(renderer));owner.Call("_sync_context_values");canvas.QueueRedraw();return;}owner.Set("_refresh_pending",true);owner.Call("_sync_context_values");
    }
    public void commit(Control owner)
