        var before=owner.Get("_before").As<Resource>();if(before==null)return;sync_selection_transform(owner);sync_linked_styles(owner);owner.Set("_sizing_preview",false);store_active_mask(owner);var undo=owner.Get("_undo").AsGodotArray();undo.Add(before);owner.Set("_before",default(Variant));if(undo.Count>40)undo.RemoveAt(0);owner.Get("_redo").AsGodotArray().Clear();owner.Set("_dirty",true);owner.Set("_refresh_pending",true);owner.Set("_tree_pending",true);owner.EmitSignal("document_changed");update_title(owner);
    }
    public void sync_selection_transform(Control owner)
    {
        var before=owner.Get("_before").As<Resource>();if(before==null||before.Get("pixel_selection").AsGodotObject()==null)return;var old=before.Get("pixel_selection_reference").As<Resource>()??_documents.layer_for_id(before,before.Get("pixel_selection_owner").AsString());var document=Document(owner);var current=_documents.layer_for_id(document,before.Get("pixel_selection_owner").AsString());if(old==null||current==null)return;var from=before.Get("pixel_selection_reference").AsGodotObject()!=null?before.Get("pixel_selection_reference_world").AsTransform2D():_documents.world_transform(before,old);var to=_documents.world_transform(document,current);var oldProperties=old.Get("properties").AsGodotDictionary();var properties=current.Get("properties").AsGodotDictionary();bool sameYaw=Mathf.IsEqualApprox(Get(oldProperties,"yaw_up_down",0).AsDouble(),Get(properties,"yaw_up_down",0).AsDouble())&&Mathf.IsEqualApprox(Get(oldProperties,"yaw_left_right",0).AsDouble(),Get(properties,"yaw_left_right",0).AsDouble());var canvas=Canvas(owner);
        if(from.IsEqualApprox(to)&&old.Get("dimensions").AsVector2().IsEqualApprox(current.Get("dimensions").AsVector2())&&sameYaw){canvas.Set("selection_forward_warp",default(Callable));canvas.Set("selection_inverse_warp",default(Callable));canvas.Set("_selection_mapping",default(Variant));canvas.Set("selection_transform",Transform2D.Identity);canvas.Set("selection_inverse",Transform2D.Identity);_canvas.update_selection_preview(canvas);owner.Set("_selection_transform_active",true);return;}
        if(!owner.Get("_selection_transform_active").AsBool()){using var image=before.Get("pixel_selection").As<Texture2D>().GetImage();canvas.Set("selection",image.Duplicate());canvas.Set("selection_texture",default(Variant));}var mapping=new ImageSelectionMapping(old,current,from,to);owner.Set("_selection_transform_active",true);canvas.Set("selection_transform",Transform2D.Identity);canvas.Set("selection_inverse",Transform2D.Identity);canvas.Set("_selection_mapping",mapping);canvas.Set("selection_forward_warp",new Callable(mapping,nameof(ImageSelectionMapping.forward)));canvas.Set("selection_inverse_warp",new Callable(mapping,nameof(ImageSelectionMapping.inverse)));_canvas.update_selection_preview(canvas);
    }
    public void cancel(Control owner)
    {
        var before=owner.Get("_before").As<Resource>();if(before==null)return;owner.Set("_sizing_preview",false);owner.Set("document",before);owner.Set("_before",default(Variant));Canvas(owner).Set("document",before);owner.Set("_refresh_pending",true);foreach(string method in new[]{"_refresh_inspector","_refresh_layers","_refresh_context"})owner.Call(method);
    }
    public void finish_pending(Control owner)
    {
        var canvas=Canvas(owner);var warp=canvas.Get("warp_tool").As<RefCounted>();var repair=canvas.Get("repair_tool").As<RefCounted>();if(warp.Get("active").AsBool())_warp.finish(warp);if(repair.Get("active").AsBool())_repair.cancel(repair);string drag=canvas.Get("_drag").AsString();if(drag is "object_preview" or "edge_pending"){if(drag=="object_preview"&&canvas.Get("_smart_ready").AsBool())_canvas.commit_object_selection(canvas);else _canvas.cancel_gesture(canvas);}if(canvas.Get("_drag").AsString() is "pixel_select" or "pixel_box" or "pixel_lasso")canvas.Call("_finish",canvas.Get("_last"));_canvas.confirm_stroke(canvas);if(owner.Get("_before").AsGodotObject()!=null)commit(owner);
    }
    private void Action(Control owner,System.Action operation){finish_pending(owner);begin(owner);operation();commit(owner);owner.Call("_refresh_inspector");owner.Call("_refresh_context");}
    public void action(Control owner,Variant operation)=>Action(owner,()=>owner.Call("_invoke_action",operation));
    public void undo(Control owner){Touch(owner);finish_pending(owner);var undo=owner.Get("_undo").AsGodotArray();if(undo.Count==0)return;owner.Get("_redo").AsGodotArray().Add(_documents.snapshot(Document(owner)));var previous=undo[undo.Count-1];undo.RemoveAt(undo.Count-1);owner.Set("document",previous);restored(owner);}
