        var canvas=Canvas(owner);var document=Document(owner);canvas.Set("document",document);var selected=canvas.Get("selected").AsGodotArray();var existing=new GArray();foreach(var id in selected)if(_documents.layer_for_id(document,id.AsString())!=null)existing.Add(id);Assign(selected,existing);if(selected.Count==0&&_documents.layer_for_id(document,document.Get("pixel_selection_owner").AsString())!=null)selected.Add(document.Get("pixel_selection_owner"));_canvas.sync_pixel_selection(canvas);string tool=canvas.Get("tool").AsString();if(tool=="pixel_select")owner.Call("_prepare_pixel_selection");if(tool=="path"){var polygon=_documents.layer_for_id(document,canvas.Get("path_layer_id").AsString());if(polygon!=null)owner.Call("_draw_custom_shape",polygon);else owner.Call("_set_tool","move");}owner.Set("_refresh_pending",true);foreach(string method in new[]{"_refresh_layers","_refresh_inspector","_refresh_context"})owner.Call(method);var browser=owner.GetNodeOrNull("MaterialBrowser");browser?.Call("refresh_from_layer");owner.Set("_dirty",true);update_title(owner);owner.EmitSignal("document_changed");
